"""Build the portable visual strategy and repository graphics from source metadata."""
from pathlib import Path
import json
from html import escape
from collections import Counter

ROOT=Path(__file__).resolve().parents[1]
def write(path,text):
 p=ROOT/path;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(text.strip()+'\n')

skills=json.loads((ROOT/'data/skills.json').read_text())
problems=json.loads((ROOT/'data/problems.json').read_text())
metrics=[
 ('K01','Verified risk mitigation','Protection','Risks with every required control implemented and currently verified ÷ identified applicable risks × 100','Confirmed risk/control baseline and current verification. This is coverage of identified risks, not a reduction in incident probability.'),
 ('K02','Unresolved critical risks','Protection','Count of critical risks with failed/unverified required protection, or no defined required control','Show consequence, owner and next action. Accepted/deferred risks remain residual.'),
 ('K03','Critical process assurance','Protection','Critical processes with their complete required control baseline verified ÷ in-scope critical processes × 100','A whole critical process requires all relevant protections; one happy path is insufficient.'),
 ('K04','Shift-left readiness','Prevention','Critical stories ready through risk/dependency review and essential decisions before development ÷ critical stories started in the cohort × 100','Source-backed start, review and decision chronology; missing timing is Not measured.'),
 ('K05','Preventive findings resolved','Prevention','Confirmed early findings resolved before affected implementation ÷ confirmed early findings requiring early resolution × 100','Decision/change evidence and timing required. Late and unresolved findings stay in the denominator.'),
 ('K06','Non-functional assurance','Protection','Agreed applicable quality requirements met with current evidence ÷ agreed applicable quality requirements × 100','Targets, workload/method and actual measurements; absent assessment is not a pass.'),
 ('K07','Integration failure-mode assurance','Diagnostics','Verified required failure-mode protections ÷ applicable required failure-mode protections × 100','Provider/operation-specific failures, limits, retries, recovery and actual downstream effects.'),
 ('K08','Source-to-outcome traceability','Diagnostics','Outcomes with all policy-required current source links and rule/version evidence ÷ outcomes in the confirmed cohort × 100','Required sources and freshness follow the actual process policy. Lineage is distinct from business-policy correctness.'),
 ('K09','Critical data-rule assurance','Diagnostics','Verified critical data rules ÷ agreed applicable critical data rules × 100','Actual schema/snapshot and independent oracles; aggregate plus row-level checks where appropriate.'),
 ('K10','Critical contract assurance','Diagnostics','Verified required critical contract obligations ÷ applicable required critical contract obligations × 100','Versioned expectations at the actual consumer/provider boundary, including agreed error behavior.'),
 ('K11','Enforced automation of critical controls','Diagnostics','Critical controls with all required assertions automated, current passing runs and gate proof ÷ critical controls × 100','Manual/unautomated controls stay in the population; files or a green badge alone are not enforcement.'),
 ('K12','Critical escape incidence','Outcomes','Mature deployed releases with a confirmed critical escape ÷ deployed releases with the observation window complete × 100','Known severity and introduced-release attribution; show immature cohort members separately.'),
 ('K13','Actionable QA feedback lead time','Outcomes','p50 / p90 elapsed hours from agreed test readiness to first actionable feedback','Show completed sample and waiting items separately; use a defined calendar and actual timestamps.'),
 ('K14','AI first-review acceptance','AI quality','AI-assisted artifacts accepted at first completed review without material correction ÷ completed first reviews × 100','Accountable review and agreed correction criteria; show unreviewed drafts separately.'),
 ('K15','Observed AI effort change','AI quality','(Comparable baseline active minutes − assisted active minutes including review/rework) ÷ baseline active minutes × 100','Matched accepted work, recorded active effort and comparable scope. Negative values are valid; this is not financial savings.'),
]
metrics=[dict(zip(['id','title','group','formula','evidence'],x)) for x in metrics]
write('data/metric-catalog.json',json.dumps(metrics,indent=2))
stages=[
 dict(title='Discover',question='What are we building, for whom and how?',output='Product, people and delivery map',skills=['00','01','02','03','05','06']),
 dict(title='Diagnose',question='Where do failure and delay actually enter?',output='Evidence-backed gap and escape analysis',skills=['22','30','31']),
 dict(title='Define',question='What protection matters most?',output='Risk/control baseline and focused plan',skills=['07','08','09']),
 dict(title='Prevent',question='What must be clarified before implementation?',output='Confirmed rules, decisions and testability',skills=['04','06','11']),
 dict(title='Design',question='How will we verify the important behavior?',output='Cases, oracles, data and readiness',skills=['10','11','12','13','15']),
 dict(title='Verify',question='What does the actual build demonstrate?',output='UI/API/data/NFR evidence and defects',skills=['14','16','17','18','19','20','21','23','24']),
 dict(title='Decide',question='What can we support with this evidence?',output='Risk-based assessment and next decision',skills=['25','26','27','28']),
 dict(title='Improve',question='What should change in the system of work?',output='Production feedback, mentoring and learning',skills=['29','30','31','32','33','34']),
]
methods=[
 ('Risk-based testing','Choose effort by consequential failure, change and uncertainty.','07 · 08 · 09'),
 ('Shift left & static review','Resolve important rules, exceptions and dependencies while decisions remain changeable.','03 · 04 · 06'),
 ('Test-design techniques','Use partitions, boundaries, decision tables and state transitions where the rules justify them.','05 · 10 · 11'),
 ('Exploratory testing','Investigate unknowns through a charter, notes and observable behavior.','19 · 22'),
 ('Layered assurance','Verify at the lowest effective layer and retain critical cross-layer journeys.','16 · 17 · 18 · 20'),
 ('Impact-based regression','Protect affected behavior using change, dependency and failure history.','23 · 24'),
 ('Quality attributes','Agree targets and verify performance, recovery, accessibility and security within scope.','21'),
 ('Root-cause & escape analysis','Separate introduction from detection gaps, then evaluate a specific correction.','22 · 30'),
 ('Agile inspection & adaptation','Fit the team’s actual flow; inspect WIP, waits, feedback and shared agreements.','00 · 09 · 30'),
 ('Mentoring & shared ownership','Develop independent judgment through real work, clear standards and feedback.','31 · 32'),
]
clients=[
 dict(name='Claude Code',label='Local project session',setup='CLAUDE.md + .claude/skills/',start='/qa-orchestrate-testing-lifecycle',note='Project skills load the authoritative procedures. Verify actual tools separately.'),
 dict(name='Gemini CLI',label='Workspace skills',setup='GEMINI.md + .gemini/skills/',start='/skills list',note='Inspect discovered skills, then request the orchestrator. Reload using /skills reload when needed.'),
 dict(name='Copilot',label='VS Code agent session',setup='.github/copilot-instructions.md + .claude/skills/',start='Apply qa-orchestrate-testing-lifecycle to these sources.',note='Confirm discovery in the actual client. Agent capabilities differ from ordinary text chat.'),
 dict(name='Any other LLM',label='Explicit source context',setup='MASTER_PROMPT.md + selected Markdown procedures',start='Read the master prompt, operating contract and procedure 00.',note='The analysis method is portable. Tool execution requires a compatible host and actual access.'),
]
data=dict(skills=skills,problems=problems,metrics=metrics,stages=stages,methods=methods,clients=clients,
 template=(ROOT/'reports/quality-report-template.html').read_text(),prompt=(ROOT/'MASTER_PROMPT.md').read_text())

def svg(content,h=360):
 return f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1200 {h}" role="img"><style>text{{font-family:Segoe UI,Arial,sans-serif}}.small{{font-size:14px;letter-spacing:2px}}.body{{font-size:18px}}.title{{font-size:30px;font-weight:650}}</style>{content}</svg>'

hero='''<rect width="1200" height="360" rx="20" fill="#153b35"/><circle cx="1110" cy="30" r="235" fill="#204d43"/><circle cx="1110" cy="30" r="155" fill="none" stroke="#41665a"/>
<text x="48" y="55" fill="#b5d6c0" class="small">EDWARD CARVAJAL MARTINEZ / QUALITY ENGINEERING</text>
<text x="48" y="125" fill="#fffdf7" font-size="47" font-weight="650">Understand deeply.</text><text x="48" y="184" fill="#fffdf7" font-size="47" font-weight="650">Prevent early. Verify what matters.</text>
<text x="48" y="237" fill="#c3d9ce" class="body">An experience-led QA strategy. Accelerated by AI. Grounded in evidence.</text>
<rect x="48" y="279" width="220" height="39" rx="19" fill="#d7edb6"/><text x="70" y="304" fill="#153b35" font-size="15" font-weight="650">35 REUSABLE SKILLS</text>
<text x="298" y="304" fill="#c3d9ce" font-size="15">Product · Process · People · Data · Delivery</text>'''
write('assets/strategy-overview.svg',svg(hero))
body='<rect width="1200" height="495" rx="20" fill="#f4f4ed"/><text x="34" y="48" class="small" fill="#557268">ONE OPERATING CYCLE / ADAPT TO THE ACTUAL CONTEXT</text>'
for i,s in enumerate(stages):
 x=34+(i%4)*292;y=85+(i//4)*190
 body+=f'<rect x="{x}" y="{y}" width="268" height="163" rx="15" fill="white" stroke="#dce5d9"/><text x="{x+20}" y="{y+32}" fill="#517a63" font-size="13">0{i+1}</text><text x="{x+20}" y="{y+70}" fill="#153b35" font-size="25" font-weight="650">{s["title"]}</text>'
 words=s['output'].split();line='';lines=[]
 for w in words:
  if len(line+' '+w)>28:lines.append(line);line=w
  else:line=(line+' '+w).strip()
 lines.append(line)
 for j,l in enumerate(lines):body+=f'<text x="{x+20}" y="{y+103+j*23}" fill="#63786d" font-size="14">{escape(l)}</text>'
 if i%4<3:body+=f'<path d="M{x+272} {y+82}h14m-5 -5 5 5-5 5" fill="none" stroke="#77977d" stroke-width="2"/>'
body+='<text x="34" y="472" fill="#557268" font-size="15">Leadership, source review and risk decisions connect every stage. Feedback returns to the relevant activity.</text>'
write('assets/method-map.svg',svg(body,495))
body='<rect width="1200" height="330" rx="20" fill="#f4f4ed"/><text x="34" y="43" class="small" fill="#557268">QUALITY EVIDENCE / FROM PREVENTION TO OBSERVED OUTCOMES</text>'
for i,(title,subtitle,items) in enumerate([
 ('Protection','Are required controls working?',['Verified risk mitigation','Critical process assurance','Unresolved critical risks']),
 ('Prevention','Are we resolving issues early?',['Shift-left readiness','Preventive findings resolved','Non-functional assurance']),
 ('Learning','What changes after delivery?',['Critical escape incidence','Actionable feedback lead time','AI review and effort evidence'])]):
 x=34+i*389
 body+=f'<rect x="{x}" y="75" width="364" height="216" rx="15" fill="white" stroke="#dce5d9"/><text x="{x+20}" y="115" fill="#153b35" font-size="25" font-weight="650">{title}</text><text x="{x+20}" y="145" fill="#63786d" font-size="15">{subtitle}</text>'
 for j,item in enumerate(items):body+=f'<circle cx="{x+23}" cy="{177+j*31}" r="4" fill="#df825d"/><text x="{x+37}" y="{182+j*31}" fill="#315a4c" font-size="15">{item}</text>'
write('assets/measurement-map.svg',svg(body,330))

