HTML=r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light"><meta name="description" content="Edward Carvajal Martinez — an experience-led QA strategy with reusable AI skills, methods and evidence-based quality metrics."><title>Quality Engineering · Edward Carvajal Martinez</title><style>__CSS__</style></head><body>
<div class="shell"><aside class="rail"><div class="brand"><div class="mark">EC</div><div><b>EDWARD CARVAJAL</b><small>QUALITY ENGINEERING</small></div></div><div class="raillabel">THE OPERATING METHOD</div><nav class="nav" role="tablist" aria-label="Strategy sections" aria-orientation="vertical">
<button id="tab-overview" role="tab" aria-selected="true" aria-controls="overview" data-page="overview"><span>01</span>Overview</button>
<button id="tab-method" role="tab" aria-selected="false" aria-controls="method" data-page="method" tabindex="-1"><span>02</span>Method</button>
<button id="tab-skills" role="tab" aria-selected="false" aria-controls="skills" data-page="skills" tabindex="-1"><span>03</span>Skill explorer</button>
<button id="tab-problems" role="tab" aria-selected="false" aria-controls="problems" data-page="problems" tabindex="-1"><span>04</span>Problem solving</button>
<button id="tab-metrics" role="tab" aria-selected="false" aria-controls="metrics" data-page="metrics" tabindex="-1"><span>05</span>Quality metrics</button>
<button id="tab-llm" role="tab" aria-selected="false" aria-controls="llm" data-page="llm" tabindex="-1"><span>06</span>LLM workflow</button></nav>
<div class="railfoot"><b>Experience-led.<br>AI-assisted.<br>Evidence-backed.</b>Product · Process · People<br>Data · Delivery</div></aside>
<main class="content"><div class="topline"><div class="eyebrow">STRATEGY & PRACTICE / SOFTWARE QUALITY</div><div class="toplinks"><span class="statusdot"><i></i>Reusable operating method</span><a href="QA_STRATEGY.md">Read strategy ↗</a><a href="docs/skills.md">Skill catalog ↗</a></div></div>
<section id="overview" class="page active" role="tabpanel" aria-labelledby="tab-overview" tabindex="0">
<div class="hero"><div><div class="eyebrow">EDWARD CARVAJAL MARTINEZ</div><h1>Understand deeply.<br>Prevent early.<br><em>Verify what matters.</em></h1><p>I turn product understanding, risk-based prevention and hands-on verification into clear quality decisions. AI accelerates the work. Experience directs it.</p><div class="herobuttons"><button class="button primary" data-go="method">Explore the method <span>→</span></button><button class="button" data-go="problems">Start with a problem</button></div><div class="principles"><span>25+ years in software QA</span><span>Cross-product approach</span><span>Any capable LLM</span></div></div>
<div class="assurance"><div class="eyebrow">THE ASSURANCE CHAIN</div><h2>Every conclusion has a path to evidence.</h2><div class="chain"><div class="chainitem"><i>01</i><div><b>Understand the source</b><small>Product, rules, people, dependencies</small></div></div><div class="chainitem"><i>02</i><div><b>Identify the risk</b><small>Failure, consequence, priority</small></div></div><div class="chainitem"><i>03</i><div><b>Verify the protection</b><small>Implemented control, actual build</small></div></div><div class="chainitem"><i>04</i><div><b>Support the decision</b><small>Evidence, residual risk, next action</small></div></div></div><div class="assurancefoot">Sources → judgment → verification → learning</div></div></div>
<div class="stats"><div class="stat"><b id="skill-total">35</b><span>reusable QA skills</span></div><div class="stat"><b>8</b><span>connected operating stages</span></div><div class="stat"><b>15</b><span>defined quality measures</span></div><div class="stat"><b>1</b><span>adaptable operating method</span></div></div>
<div class="sectionhead"><h2>Value from the first day</h2><p>A clearer picture of the real problem. A focused next action.</p></div><div class="firstday"><article class="daystep"><span class="num">01</span><h3>Learn the context</h3><p>Product, team, critical workflows and current commitments.</p></article><article class="daystep"><span class="num">02</span><h3>Trace actual work</h3><p>Follow one change and available escape evidence through delivery.</p></article><article class="daystep"><span class="num">03</span><h3>Review the risk</h3><p>Clarify consequential questions and inspect coverage with the team.</p></article><article class="daystep"><span class="num">04</span><h3>Make it actionable</h3><p>Deliver facts, open decisions, priorities and a concrete next step.</p></article></div>
<p class="note">Outputs depend on available sources and access. Continue valid analysis while execution prerequisites are resolved.</p>
<div class="grid2"><section class="panel"><div class="primaryline"><span class="pill">CATALOG STRUCTURE</span></div><h2>Coverage across the quality function</h2><p>35 unique skills, grouped by their primary purpose. These counts describe the method, not a project’s results.</p><div id="domain-chart" class="domainrows" aria-label="Skill catalog distribution"></div></section><section class="panel"><span class="pill orange">FROM ANALYSIS TO IMPACT</span><h2 style="margin-top:14px">A protection must work.</h2><p>Risk-based design establishes what needs attention. Verification shows whether the actual control works. Production feedback tests whether the improvement remains useful.</p><div class="chain"><div class="contractrow"><b>Prevent</b><span>Resolve essential ambiguity early.</span></div><div class="contractrow"><b>Verify</b><span>Check behavior across the relevant layers.</span></div><div class="contractrow"><b>Lead</b><span>Build shared judgment and ownership.</span></div><div class="contractrow"><b>Improve</b><span>Learn from real outcomes and remaining gaps.</span></div></div></section></div></section>
<section id="method" class="page" role="tabpanel" aria-labelledby="tab-method" tabindex="0"><div class="eyebrow">HOW I WORK</div><h1>One cycle.<br>Adapted to the context.</h1><p class="intro">Learn before prescribing. Connect prevention, verification and leadership. Return to the relevant stage when evidence or the product changes.</p><div id="stage-grid" class="looprow"></div><div id="stage-detail" class="stagedetail" aria-live="polite"></div><div class="sectionhead"><h2>Methods selected by the problem</h2><a class="textlink" href="docs/methods.md">Read the selection rationale ↗</a></div><div id="method-grid" class="techniques"></div></section>
<section id="skills" class="page" role="tabpanel" aria-labelledby="tab-skills" tabindex="0"><div class="eyebrow">REUSABLE PROFESSIONAL REASONING</div><h1>Explore the skills.</h1><p class="intro">Each skill has a purpose, source inputs and a reviewable output. Select a card to inspect its contract and reusable instruction.</p><div class="filters"><label class="sr" for="skill-search">Search skills</label><input id="skill-search" placeholder="Search risk, SQL, mentoring, APIs…" type="search"><label class="sr" for="skill-group">Filter by domain</label><select id="skill-group"><option value="all">All domains</option></select></div><div id="skill-count" class="catalogcount" aria-live="polite"></div><div id="skill-grid" class="skillgrid"></div><p id="no-skills" class="empty" hidden>No skills match this selection.</p></section>
<section id="problems" class="page" role="tabpanel" aria-labelledby="tab-problems" tabindex="0"><div class="eyebrow">EVIDENCE-LED PROBLEM SOLVING</div><h1>Start with the problem.<br>Find the mechanism.</h1><p class="intro">The first intervention follows the diagnosis. These are reusable investigation paths, not assumptions about a company or findings from an unassessed product.</p><div class="problemgrid"><div id="problem-nav" class="problemnav" aria-label="Problem patterns"></div><div id="problem-view" class="problemview" aria-live="polite"></div></div></section>
<section id="metrics" class="page" role="tabpanel" aria-labelledby="tab-metrics" tabindex="0"><div class="eyebrow">PROTECTION · PREVENTION · OUTCOMES</div><h1>Measure what<br>supports a decision.</h1><p class="intro">Exact formulas, defined populations and traceable evidence. Six primary measures lead the assessment; supporting diagnostics explain the gap.</p><div class="evidencebox"><h2 id="evidence-title">Project evidence workspace</h2><p id="evidence-note">No project ledger loaded. Browse the definitions below or load an actual reviewed PROCESS_RISK JSON ledger to display observed risk/control coverage.</p><div class="evidenceactions"><button class="button" id="load-evidence">Load evidence JSON</button><input id="evidence-file" type="file" accept="application/json,.json" hidden><button class="button" id="export-report" disabled>Download quality report</button><button class="button" id="clear-evidence" disabled>Clear evidence</button></div><div id="evidence-error" class="errorbox" role="alert" hidden></div><div id="evidence-chart" class="evidencechart" hidden></div></div><div id="metric-filter" class="metricfilter" aria-label="Metric categories"></div><div id="metric-grid" class="metriccards"></div><p class="note">Missing baseline → Not measured. Confirmed zero denominator → No data. An accepted risk remains residual. A high aggregate cannot waive an essential failed or missing control.</p><a class="textlink" href="docs/metrics.md">Primary definitions ↗</a> &nbsp; <a class="textlink" href="docs/quality-diagnostics.md">Diagnostic definitions ↗</a></section>
<section id="llm" class="page" role="tabpanel" aria-labelledby="tab-llm" tabindex="0"><div class="eyebrow">MODEL-PORTABLE · HUMAN-ACCOUNTABLE</div><h1>The method travels.<br>The tools depend on the host.</h1><p class="intro">The same source-grounded procedure works with different LLMs. Client discovery loads the instructions; actual capabilities enable execution.</p><div class="aiflow"><article class="card"><span class="num">01</span><h3>Provide sources</h3><p>Scope, current rules, dependencies and evidence.</p></article><article class="card"><span class="num">02</span><h3>Select the skill</h3><p>Load only the reasoning needed for the task.</p></article><article class="card"><span class="num">03</span><h3>Review the proposal</h3><p>Confirm expectations and correct unsupported assumptions.</p></article><article class="card"><span class="num">04</span><h3>Verify with real tools</h3><p>Use the actual build, data and authorized runtime.</p></article><article class="card"><span class="num">05</span><h3>Preserve evidence</h3><p>Record sources, runs, chronology and limitations.</p></article><article class="card"><span class="num">06</span><h3>Make the decision</h3><p>Explain protection, remaining risk and next action.</p></article></div><div id="client-grid" class="clientgrid"></div><div class="sectionhead"><h2>One reusable starting instruction</h2><a class="textlink" href="docs/llm-clients.md">Client-specific details ↗</a></div><div class="prompts"><div class="promptheader"><h2 style="margin:0">Apply the next valid stage.</h2><button class="button" id="copy-master">Copy instruction</button></div><pre id="master-text"></pre></div></section>
<footer class="footer"><span>Edward Carvajal Martinez · Senior QA / QA Lead · Quality Engineering</span><span>Authored method and catalog structure. Project outcomes require actual evidence.</span></footer></main></div>
<dialog id="skill-dialog" aria-labelledby="dialog-title"><div class="dialogbody"><div class="dialogtop"><span id="dialog-id" class="pill"></span><button class="close" id="close-dialog" aria-label="Close skill details">×</button></div><h2 id="dialog-title"></h2><p id="dialog-purpose"></p><div class="contractrow"><b>Inputs</b><span id="dialog-inputs"></span></div><div class="contractrow"><b>Output</b><span id="dialog-output"></span></div><div class="contractrow"><b>Practice</b><span id="dialog-methods"></span></div><div class="sectionhead"><h3 style="margin:0">Reusable instruction</h3><button class="button" id="copy-skill">Copy</button></div><pre id="dialog-prompt"></pre><a class="textlink" id="dialog-source" href="#">Read authoritative procedure ↗</a></div></dialog>
<div id="toast" class="toast" role="status" hidden></div><noscript><p style="padding:24px">Open README.md and docs/skills.md for the complete readable strategy. The interactive controls require JavaScript.</p></noscript>
<script id="strategy-data" type="application/json">__DATA__</script><script>__ENGINE__</script><script>__JS__</script></body></html>'''

JS=r'''
'use strict';
const D=JSON.parse(document.getElementById('strategy-data').textContent),$=id=>document.getElementById(id);
const e=(tag,cls,text)=>{const n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n};
let currentSkill=null,loaded=null,metricGroup='Primary';
function go(name,focus=false){if(!document.getElementById(name)?.classList.contains('page'))return;for(const n of document.querySelectorAll('.page'))n.classList.toggle('active',n.id===name);for(const b of document.querySelectorAll('[data-page]')){const on=b.dataset.page===name;b.setAttribute('aria-selected',String(on));b.tabIndex=on?0:-1;}history.replaceState(null,'','#'+name);if(focus)$('tab-'+name).focus();window.scrollTo({top:0,behavior:'instant'});}
for(const b of document.querySelectorAll('[data-page]'))b.addEventListener('click',()=>go(b.dataset.page));
for(const b of document.querySelectorAll('[data-go]'))b.addEventListener('click',()=>go(b.dataset.go,true));
document.querySelector('.nav').addEventListener('keydown',event=>{const keys=['ArrowDown','ArrowRight','ArrowUp','ArrowLeft','Home','End'];if(!keys.includes(event.key))return;const tabs=[...document.querySelectorAll('[data-page]')];let i=tabs.indexOf(document.activeElement);if(i<0)return;event.preventDefault();if(event.key==='Home')i=0;else if(event.key==='End')i=tabs.length-1;else i=(i+(['ArrowUp','ArrowLeft'].includes(event.key)?-1:1)+tabs.length)%tabs.length;go(tabs[i].dataset.page,true)});
function toast(s){$('toast').textContent=s;$('toast').hidden=false;setTimeout(()=>$('toast').hidden=true,2200)}
async function copy(s){try{await navigator.clipboard.writeText(s);toast('Instruction copied')}catch{const t=e('textarea');t.value=s;document.body.append(t);t.select();const ok=document.execCommand('copy');t.remove();toast(ok?'Instruction copied':'Select and copy the visible instruction')}}
const groups=[...new Set(D.skills.map(s=>s.group))];for(const group of groups){const count=D.skills.filter(s=>s.group===group).length;const row=e('div','domainrow');const track=e('div','bartrack'),fill=e('div','barfill');fill.style.width=(100*count/Math.max(...groups.map(g=>D.skills.filter(s=>s.group===g).length)))+'%';track.append(fill);row.append(e('span','',group),track,e('b','',String(count)));$('domain-chart').append(row);const option=e('option','',group);option.value=group;$('skill-group').append(option)}
function showStage(i){const stage=D.stages[i];for(const [j,b] of [...$('stage-grid').children].entries()){b.classList.toggle('selected',i===j);b.setAttribute('aria-pressed',String(i===j))}const left=e('div'),right=e('div');left.append(e('h3','',stage.question),e('p','','Output: '+stage.output));right.append(e('h3','','Relevant skills'));const links=e('div','linkrow');for(const id of stage.skills){const s=D.skills.find(x=>x.id===id),b=e('button','chipbutton',id+' · '+s.title);b.addEventListener('click',()=>openSkill(s));links.append(b)}right.append(links);$('stage-detail').replaceChildren(left,right)}
D.stages.forEach((s,i)=>{const b=e('button','stage');b.append(e('span','step','0'+(i+1)+' / OPERATING STAGE'),e('strong','',s.title),e('small','',s.output));b.addEventListener('click',()=>showStage(i));$('stage-grid').append(b)});showStage(0);
for(const [title,text,ids] of D.methods){const card=e('article','card');card.append(e('h3','',title),e('p','',text),e('span','pill',ids));$('method-grid').append(card)}
function openSkill(s){currentSkill=s;$('dialog-id').textContent='SKILL '+s.id+' / '+s.group;$('dialog-title').textContent=s.title;$('dialog-purpose').textContent=s.purpose;for(const [id,key] of [['dialog-inputs','inputs'],['dialog-output','output'],['dialog-methods','methods'],['dialog-prompt','prompt']])$(id).textContent=s[key];$('dialog-source').href=s.path;$('skill-dialog').showModal()}
$('close-dialog').addEventListener('click',()=>$('skill-dialog').close());$('copy-skill').addEventListener('click',()=>copy(currentSkill.prompt));
function renderSkills(){const query=$('skill-search').value.trim().toLowerCase(),group=$('skill-group').value;const selected=D.skills.filter(s=>(group==='all'||s.group===group)&&[s.id,s.title,s.purpose,s.inputs,s.output,s.methods].join(' ').toLowerCase().includes(query));$('skill-grid').replaceChildren();for(const s of selected){const card=e('article','skillcard'),top=e('div','skilltop');top.append(e('span','skillid',s.id),e('span','pill',s.stage));const b=e('button','','Inspect skill →');b.addEventListener('click',()=>openSkill(s));b.setAttribute('aria-label','Inspect skill '+s.id+': '+s.title);card.append(top,e('h3','',s.title),e('p','',s.purpose),b);$('skill-grid').append(card)}$('skill-count').textContent=selected.length+' / '+D.skills.length+' skills · source → reasoning → artifact';$('no-skills').hidden=selected.length!==0}
$('skill-search').addEventListener('input',renderSkills);$('skill-group').addEventListener('change',renderSkills);renderSkills();
function showProblem(p){for(const b of $('problem-nav').children){const on=b.dataset.id===p.id;b.classList.toggle('selected',on);b.setAttribute('aria-pressed',String(on))}const flow=e('div','problemflow');for(const [i,title,key] of [[1,'Investigate the mechanism','investigate'],[2,'Choose the first intervention','action'],[3,'Verify the effect','proof']]){const row=e('div','problemitem'),text=e('div');text.append(e('h3','',title),e('p','',p[key]));row.append(e('span','','0'+i),text);flow.append(row)}const links=e('div','linkrow');for(const id of p.skills){const s=D.skills.find(s=>s.id===id),b=e('button','chipbutton','Skill '+id);b.addEventListener('click',()=>openSkill(s));links.append(b)}const measures=e('p','note','Measures: '+p.metrics.map(id=>id+' '+D.metrics.find(m=>m.id===id).title).join(' · '));$('problem-view').replaceChildren(e('span','pill orange','PROBLEM PATTERN'),e('h2','',p.title),e('p','intro',p.signal),flow,links,measures)}
for(const p of D.problems){const b=e('button','',p.title);b.dataset.id=p.id;b.addEventListener('click',()=>showProblem(p));$('problem-nav').append(b)}showProblem(D.problems[0]);
const filters=['Primary','All','Protection','Prevention','Diagnostics','Outcomes','AI quality'];for(const group of filters){const b=e('button','',group);b.dataset.metricgroup=group;b.addEventListener('click',()=>{metricGroup=group;renderMetrics()});$('metric-filter').append(b)}
function primaryValues(d){const m=QAMetrics.calculateProcessMetrics(d),riskKnown=d.risk_baseline_status==='Established'||d.risks.length>0,processKnown=d.process_baseline_status==='Established'||d.processes.length>0;return {K01:riskKnown?QAMetrics.percent(m.verified.length,d.risks.length):'Not measured',K02:riskKnown?String(m.unresolved.length):'Not measured',K03:processKnown?QAMetrics.percent(m.assured.length,m.processes.length):'Not measured',K04:m.early.value,K05:m.prevention.value,K06:m.nfr.value}}
function renderMetrics(){for(const b of $('metric-filter').children){const on=b.dataset.metricgroup===metricGroup;b.classList.toggle('active',on);b.setAttribute('aria-pressed',String(on))}const selected=D.metrics.filter(m=>metricGroup==='All'||(metricGroup==='Primary'?Number(m.id.slice(1))<=6:m.group===metricGroup));const values=loaded?primaryValues(loaded):{};$('metric-grid').replaceChildren();for(const m of selected){const card=e('article','metriccard');card.append(e('span','pill',m.id+' / '+m.group),e('h3','',m.title),e('div','formula',m.formula),e('p','',m.evidence));if(loaded&&values[m.id]!==undefined)card.append(e('div','metricvalue',values[m.id]));$('metric-grid').append(card)}}renderMetrics();
function clearEvidence(){loaded=null;$('evidence-title').textContent='Project evidence workspace';$('evidence-note').textContent='No project ledger loaded. Browse the definitions below or load an actual reviewed PROCESS_RISK JSON ledger to display observed risk/control coverage.';$('evidence-chart').replaceChildren();$('evidence-chart').hidden=true;$('evidence-error').hidden=true;$('export-report').disabled=true;$('clear-evidence').disabled=true;renderMetrics()}
$('load-evidence').addEventListener('click',()=>$('evidence-file').click());$('clear-evidence').addEventListener('click',clearEvidence);
$('evidence-file').addEventListener('change',async event=>{const f=event.target.files[0];if(!f)return;try{if(f.size>2000000)throw Error('Use a reviewed ledger under 2 MB.');const d=JSON.parse(await f.text());if(d.is_simulated)throw Error('This workspace accepts actual sourced project records. Keep synthetic validation inputs separate.');QAMetrics.validate(d);loaded=d;$('evidence-title').textContent=d.title;$('evidence-note').textContent='Source: '+d.source+' · Scope: '+d.target+' · Build: '+d.build+'. The chart summarizes supplied records; source review establishes truth and applicability.';const chart=$('evidence-chart');chart.replaceChildren();const states=['Verified mitigated','Control failed','Not verified'];for(const state of states){const n=d.risks.filter(r=>QAMetrics.riskState(r,d)===state).length;const row=e('div','evidencerow'),track=e('div','bartrack'),fill=e('div','barfill');fill.style.width=(d.risks.length?100*n/d.risks.length:0)+'%';track.append(fill);row.append(e('span','',state),track,e('b','',String(n)));chart.append(row)}chart.hidden=d.risks.length===0;$('export-report').disabled=false;$('clear-evidence').disabled=false;$('evidence-error').hidden=true;renderMetrics()}catch(error){$('evidence-error').textContent='Evidence not loaded. '+error.message;$('evidence-error').hidden=false}finally{event.target.value=''}});
$('export-report').addEventListener('click',()=>{if(!loaded)return;const payload=JSON.stringify(loaded,null,2).replaceAll('<','\\u003c');const html=D.template.replace(/(<script id="qa-report-data" type="application\/json">)[\s\S]*?(<\/script>)/,(_,a,b)=>a+payload+b);const url=URL.createObjectURL(new Blob([html],{type:'text/html'})),a=e('a');a.href=url;a.download='quality-report.html';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)});
for(const c of D.clients){const card=e('article','clientcard');card.append(e('span','pill',c.label),e('h2','',c.name),e('div','setup',c.setup),e('code','',c.start),e('p','',c.note));$('client-grid').append(card)}
const master=D.prompt.match(/```text\n([\s\S]*?)```/)[1].trim();$('master-text').textContent=master;$('copy-master').addEventListener('click',()=>copy(master));
if(location.hash)go(location.hash.slice(1));
window.__QA_STRATEGY={skills:D.skills.length,stages:D.stages.length,metrics:D.metrics.length,problems:D.problems.length,groups};
'''

template=(ROOT/'reports/quality-report-template.html').read_text()
base=template[template.index('function validateBase('):template.index('function metrics(')]
process=template[template.index('function allVerified('):template.index('function render(d)')]
engine="(function(root){'use strict';\nconst STATES=['Passed','Failed','Blocked','Not Run','Not Applicable'];\nfunction percent(n,d){return d?Number((100*n/d).toFixed(1))+'%':'No data'}\n"+base+process+"\nconst api={validate,calculateProcessMetrics,riskState,percent};if(typeof module==='object'&&module.exports)module.exports=api;else root.QAMetrics=api;})(typeof window!=='undefined'?window:globalThis);\n"
write('scripts/quality_metrics.js',engine)
html=HTML.replace('__CSS__',CSS).replace('__DATA__',json.dumps(data).replace('<','\\u003c')).replace('__ENGINE__',engine).replace('__JS__',JS)
write('index.html',html)
print(f'Built visual strategy: {len(skills)} skills, {len(stages)} stages, {len(metrics)} measures, {len(problems)} problem patterns; 3 repository SVGs.')
